{   size_t const sampleSize = 1024;
    ZSTD_CCtx* const cctx = ZSTD_createCCtx();
    ZSTD_inBuffer inb;
    ZSTD_outBuffer outb;
    inb.src = CNBuffer;
    inb.pos = 0;
    inb.size = 0;
    outb.dst = compressedBuffer;
    outb.pos = 0;
    outb.size = compressedBufferSize;
    CHECK_Z( ZSTD_CCtx_setParameter(cctx, ZSTD_c_compressionLevel, ZSTD_maxCLevel()) );

