        U32 rand32 = FUZ_rand(&seed_copy);
        U64 rand64 = ((U64)FUZ_rand(&seed_copy) << 32) | FUZ_rand(&seed_copy);
        U32 lowbit_only_32 = 1;
        U64 lowbit_only_64 = 1;
        U32 highbit_only_32 = (U32)1 << 31;
        U64 highbit_only_64 = (U64)1 << 63;
        U32 i;
