        CHECK_EQ(ZSTD_highbit32(highbit_only_32), 31u);

        /* Test ZSTD_NbCommonBytes */
        if (MEM_isLittleEndian()) {
            if (MEM_64bits()) {
                CHECK_EQ(ZSTD_NbCommonBytes(lowbit_only_32), 0u);
                CHECK_EQ(ZSTD_NbCommonBytes(highbit_only_32), 3u);
            } else {
                CHECK_EQ(ZSTD_NbCommonBytes(lowbit_only_32), 0u);
                CHECK_EQ(ZSTD_NbCommonBytes(highbit_only_32), 3u);
